#include <vector>
#include <cmath>

// Include the function declaration (actually the solution code above will be placed here)

int main() {
    // Test 1: 1D system: [2] as target, other column [1]. 2 = 2*1, conic combination.
    {
        std::vector<std::vector<double>> A = {{1.0, 2.0}}; // one row, two cols: col0 is [1], col1 is [2]
        assert(hasConicCombination(A, 1)); // target col1 (2) can be 2 * col0 (1)
    }
    // Test 2: Target cannot be formed: [1] vs [2]? Actually if target is 1 and other is 2, need x*2=1 with x>=0 -> x=0.5, so yes.
    {
        std::vector<std::vector<double>> A = {{2.0, 1.0}};
        assert(hasConicCombination(A, 1)); // target col1 (1) = 0.5 * col0 (2)
    }
    // Test 3: Negative combination needed: [ -1 ] vs [1] -> need x=-1 not allowed.
    {
        std::vector<std::vector<double>> A = {{1.0, -1.0}};
        assert(!hasConicCombination(A, 1)); // -1 cannot be nonnegative multiple of 1
    }
    // Test 4: Zero target always feasible.
    {
        std::vector<std::vector<double>> A = {{1.0, 0.0}};
        assert(hasConicCombination(A, 1)); // zero target, x=0
    }
    // Test 5: 2D case: columns [1,0]^T and [0,1]^T, target [2,3]^T feasible.
    {
        std::vector<std::vector<double>> A = {
            {1.0, 0.0, 2.0},
            {0.0, 1.0, 3.0}
        };
        assert(hasConicCombination(A, 2)); // target col2 = 2*col0 + 3*col1
    }
    // Test 6: 2D case: target [1, -1] not feasible with nonnegative combos.
    {
        std::vector<std::vector<double>> A = {
            {1.0, 0.0, 1.0},
            {0.0, 1.0, -1.0}
        };
        assert(!hasConicCombination(A, 2)); // need y negative
    }
    // Test 7: Singular case: two identical columns [1,1] and [1,1], target [2,2].
    {
        std::vector<std::vector<double>> A = {
            {1.0, 1.0, 2.0},
            {1.0, 1.0, 2.0}
        };
        assert(hasConicCombination(A, 2)); // 2 * col0 works
    }
    // Test 8: Inconsistent dependent case: columns [1,2], [2,4], target [3,6] feasible (1.5*col0)
    {
        std::vector<std::vector<double>> A = {
            {1.0, 2.0, 3.0},
            {2.0, 4.0, 6.0}
        };
        assert(hasConicCombination(A, 2));
    }
    // Test 9: target requires negative coefficients even though columns are independent.
    {
        std::vector<std::vector<double>> A = {
            {1.0, 0.0, -1.0},
            {0.0, 1.0, -1.0}
        };
        assert(!hasConicCombination(A, 2)); // need (-1,-1) not nonneg
    }
    // Test 10: n==1 case.
    {
        std::vector<std::vector<double>> A = {{5.0}};
        assert(!hasConicCombination(A, 0));
    }
    return 0;
}
